-- V3_1 (T05): obiective reale din Arad + texte de ghid. Surse și verificări: docs/ARAD-DATA.md.
-- Coordonatele sunt aproximative (±100 m) — de verificat pe hartă. Textele sunt scrise pentru citire/TTS (propoziții scurte).

INSERT INTO places (id, name, slug, type, description, address, lat, lng, image_url, image_credit, opening_hours, visit_minutes, tags, rating, parking_hint, exterior_only) VALUES
(1, 'Cetatea Aradului', 'cetatea-aradului', 'ATTRACTION',
 $$Fortificație în stil Vauban, în formă de stea cu șase bastioane, ridicată între 1763 și 1783 în bucla Mureșului. Este monumentul istoric cel mai important al orașului. Interiorul e unitate militară și nu se vizitează; zidurile, șanțul și Monumentul celor 13 Generali se văd din exterior, dintr-o plimbare prin Subcetate și de pe Faleză.$$,
 'Cartier Subcetate, Arad', 46.1711, 21.3319, NULL, 'Foto: Vasile Topac, CC BY-SA 3.0 RO, Wikimedia Commons (de descărcat)', 'Exteriorul: oricând. Interiorul nu se vizitează (unitate militară).', 60, 'istorie,familie,foto,in-aer-liber', 4.6, 'Piața 13 Martiri (Subcetate) sau parcarea de la Ștrandul Neptun, apoi pe jos', true),
(2, 'Palatul Cultural', 'palatul-cultural', 'MUSEUM',
 $$Clădire-simbol a Aradului, construită între 1911 și 1913 după planurile arhitectului Ludovic Szántay. Găzduiește Sala Filarmonicii și secțiile Complexului Muzeal Arad: Muzeul de Istorie și Arheologie (cu o sală imersivă), Muzeul de Științe ale Naturii și Pinacoteca.$$,
 'Piața George Enescu 1, Arad (intrarea la muzeu dinspre Bd. Dragalina)', 46.1757, 21.3171, NULL, 'Foto: Chainwit., CC BY 4.0, Wikimedia Commons (de descărcat)', 'Muzeu: marți–duminică 09:00–17:00 (ultima intrare 16:30), luni închis. Bilet 13,5 lei/secție, 47 lei toate expozițiile, Pinacoteca 16,5 lei.', 75, 'muzee,istorie,arta,familie', 4.7, 'Bd. Dragalina / Parcul Copiilor', false),
(3, 'Teatrul Clasic „Ioan Slavici”', 'teatrul-clasic-ioan-slavici', 'VENUE',
 $$Teatrul orașului, inaugurat în 1874, în stil neoclasic, pe Bulevardul Revoluției, la Piața Avram Iancu. Are Sala Mare și Sala Studio și găzduiește în fiecare noiembrie Festivalul Internațional de Teatru Nou.$$,
 'Bd. Revoluției 103, Arad', 46.1726, 21.3153, NULL, NULL, 'Agenția de bilete: marți, miercuri, vineri 12:00–14:00; joi 12:00–14:00 și 17:00–19:00. Bilete online pe eventim.ro.', 20, 'cultura,istorie,arhitectura', 4.6, 'Piața Avram Iancu', false),
(4, 'Palatul Administrativ (Primăria)', 'palatul-administrativ', 'ATTRACTION',
 $$Sediul Primăriei, construit între 1872 și 1874 în stil neorenascentist. Turnul de 54 de metri are un orologiu adus din Elveția, care cântă „Oda bucuriei” la ore fixe. Clădirea domină Bulevardul Revoluției.$$,
 'Bd. Revoluției 75, Arad', 46.1768, 21.3145, NULL, NULL, 'Exteriorul oricând; interiorul doar la tururi ocazionale.', 15, 'arhitectura,istorie,foto', 4.6, 'Parcarea din spatele Palatului / Parcul Reconcilierii', false),
(5, 'Biserica Roșie', 'biserica-rosie', 'ATTRACTION',
 $$Biserica evanghelică-luterană, construită în 1905–1906 în stil neogotic, după planurile lui Ludovic Szántay. Numele vine de la cărămida roșie șlefuită a fațadelor. Turnul are 46 de metri. Găzduiește uneori concerte de orgă.$$,
 'Bd. Revoluției 61, Arad', 46.1740, 21.3160, NULL, NULL, 'De obicei deschisă ziua; concerte anunțate de Filarmonică.', 15, 'arhitectura,foto', 4.5, 'Bd. Revoluției (parcare cu plată)', false),
(6, 'Catedrala Ortodoxă „Sfânta Treime”', 'catedrala-sfanta-treime', 'ATTRACTION',
 $$Catedrala arhiepiscopală a Aradului, începută în 1991 și sfințită în 2008, cu pictura interioară finalizată în 2018. Este cea mai mare biserică ortodoxă din vestul României. În piața din față se ține în fiecare iarnă Târgul de Crăciun.$$,
 'Piața Catedralei, Arad', 46.1692, 21.3182, NULL, NULL, 'Deschisă zilnic.', 20, 'arhitectura,spiritual,foto', 4.7, 'Parcarea din Piața Catedralei (ocupată în perioada Târgului de Crăciun)', false),
(7, 'Catedrala Romano-Catolică „Sfântul Anton de Padova”', 'catedrala-sf-anton', 'ATTRACTION',
 $$Construită între 1902 și 1904 după planurile arhitectului Emil Tabacovici, cu o fațadă monumentală cu coloane. Deasupra intrării se află o copie în marmură a Pietà de Michelangelo.$$,
 'Bd. Revoluției 96A, Arad', 46.1752, 21.3151, NULL, NULL, 'Deschisă ziua.', 15, 'arhitectura,arta', 4.5, 'Bd. Revoluției', false),
(8, 'Turnul de Apă', 'turnul-de-apa', 'ATTRACTION',
 $$Turn de 35 de metri construit în 1896 de firma engleză Shone & Ault, în forma unui donjon medieval. A alimentat orașul cu apă până în 1956. A găzduit o galerie de artă și un muzeu al apei, dar din 2024 este închis publicului; se admiră din exterior, lângă Parcul Reconcilierii.$$,
 'Str. Piotr Ilici Ceaikovski 11, Arad', 46.1792, 21.3118, NULL, NULL, 'Închis publicului. Exteriorul oricând.', 15, 'arhitectura,istorie,foto', 4.3, 'Parcul Reconcilierii', true),
(9, 'Faleza Mureșului', 'faleza-muresului', 'PARK',
 $$Promenada de pe malul Mureșului, lungă de câțiva kilometri, cu Parcul Copiilor, Parcul Eminescu, Ștrandul Neptun, terenuri de sport și locuri de joacă. Locul preferat al arădenilor pentru plimbări și alergat, cu vedere spre Cetate.$$,
 'Malul drept al Mureșului, Arad', 46.1745, 21.3215, NULL, NULL, 'Oricând.', 45, 'natura,familie,sport,in-aer-liber', 4.6, 'Ștrandul Neptun / Bd. Dragalina', false),
(10, 'Parcul Natural Lunca Mureșului – Pădurea Ceala', 'lunca-muresului-ceala', 'NATURE',
 $$Arie naturală protejată la marginea de vest a orașului, cu pădure de luncă, brațe moarte ale Mureșului, trasee de plimbare și bicicletă și observatoare de păsări. Centrul de vizitare Ceala este punctul de plecare.$$,
 'Pădurea Ceala, Arad', 46.1900, 21.2650, NULL, NULL, 'Oricând; Centrul de vizitare are program propriu.', 120, 'natura,familie,sport,in-aer-liber', 4.5, 'Parcarea de la intrarea în Pădurea Ceala', false),
(11, 'Podgoria Miniș–Măderat și Muzeul Viei și Vinului', 'podgoria-minis', 'WINERY',
 $$Una dintre cele mai vechi podgorii din România, la 25 km est de Arad, pe dealurile Zarandului. Vinul-emblemă este Cadarca roșie; alături, Mustoasa de Măderat, Fetească regală, Riesling italian. Muzeul Viei și Vinului din Miniș (1988) și cramele din zonă primesc vizitatori cu rezervare. Se ajunge și cu tramvaiul Arad–Ghioroc.$$,
 'Miniș, comuna Ghioroc, jud. Arad', 46.1370, 21.6050, NULL, NULL, 'Muzeul: marți–duminică 09:00–17:00. Cramele: degustări cu rezervare, de obicei în timpul săptămânii 09:00–17:00, în weekend doar grupuri.', 150, 'vin,gastronomie,natura', 4.7, 'La muzeu și la crame; în sat, parcări libere', false),
(12, 'Castelul Macea și Grădina Botanică „Pavel Covaci”', 'castelul-macea', 'ATTRACTION',
 $$Castel nobiliar în stil baroc târziu, cu elemente gotice, înconjurat de o grădină botanică universitară de 21,5 hectare, cu peste 3.800 de specii: alpinariu, rozariu, colecție dendrologică, muzee botanic, etnografic și cinegetic. La 25 km nord de Arad.$$,
 'Comuna Macea, jud. Arad', 46.3860, 21.3167, NULL, NULL, 'Luni–vineri 08:00–16:00; sâmbătă–duminică 09:00–19:00 (martie–noiembrie); închis decembrie–februarie. Tel. 0771 179 772.', 90, 'natura,familie,arhitectura,foto', 4.7, 'Parcare la intrarea în grădină', false)
ON CONFLICT (id) DO NOTHING;

INSERT INTO guide_points (place_id, position, title, text, lat, lng, duration_sec) VALUES
-- 1 · Cetatea Aradului (exterior)
(1, 1, 'Monumentul celor 13 Generali', $$Începem în Piața 13 Martiri, din Subcetate. Obeliscul din marmură gri a fost ridicat în 1881 din contribuția locuitorilor, pe o movilă artificială. Pe laturile lui sunt scrise numele celor 13 generali ai armatei revoluționare maghiare, executați lângă zidurile cetății la 6 octombrie 1849, și data execuției. Este unul dintre cele mai importante locuri de memorie din Arad și punctul de unde se vede cel mai bine conturul fortificației.$$, 46.1685, 21.3290, 120),
(1, 2, 'De ce o cetate în bucla Mureșului', $$Priviți spre valul de pământ și șanțul din fața zidurilor. După ce Banatul a intrat sub Habsburgi, împărăteasa Maria Terezia a hotărât construirea unei fortificații moderne, pe malul stâng al Mureșului, într-o peninsulă apărată natural de râu pe trei laturi. Lucrările au început în 1763, după planurile arhitectului militar Ferdinand Philipp von Harsch, și au durat douăzeci de ani. Pentru ea au fost demolate 168 de case și au lucrat mii de oameni; cărămida venea, spune tradiția, din mână în mână, de la Jimbolia.$$, 46.1700, 21.3300, 150),
(1, 3, 'Steaua cu șase bastioane', $$Cetatea are forma unei stele duble cu șase colțuri, în sistemul Vauban de tip „tenaille”, adică în foarfece. Zidurile au o circumferință de 3.180 de metri, iar bastioanele și redutele pentagonale aveau 296 de guri de foc. Unghiurile zidurilor erau calculate ca proiectilele să ricoșeze, iar pământul din spatele cărămizii amortiza exploziile. Construcția a costat peste trei milioane de florini. Era, la vremea ei, una dintre cele mai moderne fortificații din estul imperiului.$$, 46.1711, 21.3319, 150),
(1, 4, 'Închisoare, nu câmp de luptă', $$Cetatea nu a fost niciodată cucerită, dar a fost folosită mai ales ca închisoare militară. În 1784 au fost închiși aici Horea, Cloșca și Crișan, conducătorii răscoalei țăranilor. Între 1790 și 1815 au fost ținuți prizonieri francezi, iar în 1849 revoluționarul Eftimie Murgu. După revoluția maghiară din 1848–1849, în cetate a funcționat tribunalul militar austriac care i-a condamnat pe cei 13 generali.$$, 46.1711, 21.3319, 120),
(1, 5, 'Biserica Franciscană și garnizoana de azi', $$În incintă se află Biserica Franciscană, ridicată odată cu cetatea, în stil baroc; în caz de asediu, mănăstirea devenea spital. Ansamblul este monument istoric de importanță națională, dar interiorul rămâne unitate militară, aici fiind și garnizoana unui batalion de infanterie. Porțile se deschid rar, la evenimente precum Crosul Cetăților. Cel mai bun loc pentru fotografii este de pe Faleză, de peste râu, mai ales seara.$$, 46.1730, 21.3290, 120),

-- 2 · Palatul Cultural
(2, 1, 'Fațada și arhitectul Szántay', $$Palatul Cultural a fost construit între 1911 și 1913, după planurile lui Ludovic Szántay, arhitectul care a desenat și Biserica Roșie. Fațada principală, spre Mureș, are un portic cu coloane în spirit neoclasic, iar restul clădirii amestecă stiluri, așa cum era moda epocii. A fost gândit de la început ca un „palat al culturii”: muzeu, bibliotecă, sală de concerte, toate sub același acoperiș.$$, 46.1757, 21.3171, 120),
(2, 2, 'Sala Filarmonicii', $$Sala mare găzduiește Filarmonica Arad, cu o stagiune bogată: în noiembrie, Festivalul Internațional „Toamna Muzicală Arădeană”, apoi concerte vocal-simfonice și de sărbători. Biletele se cumpără la casieria de la intrare, deschisă în zilele de concert dimineața și cu o oră înainte de spectacol. Chiar dacă nu mergeți la concert, holul merită o privire.$$, 46.1757, 21.3171, 90),
(2, 3, 'Muzeul de Istorie și sala imersivă', $$Intrarea la muzeu este dinspre Bulevardul Dragalina, lângă Parcul Copiilor. Expoziția de arheologie parcurge toate epocile, de la preistorie la epoca modernă, iar sala imersivă vă duce în fortificația din epoca bronzului de la Sântana–Cetatea Veche. Nu ratați „Tezaur 1848–1849”, cu cele mai valoroase obiecte ale colecției, în jurul cărora s-a născut muzeul arădean, acum peste 130 de ani.$$, 46.1757, 21.3171, 120),
(2, 4, 'Științele Naturii și Pinacoteca', $$La etaj, Muzeul de Științe ale Naturii are expoziția „Planeta noastră în miniatură”, iar Pinacoteca adună pictură și sculptură din colecțiile arădene, cu lucrări ale artiștilor locali. Muzeul e deschis de marți până duminică, între 9 și 17, cu ultima intrare la 16:30. Un bilet pentru toate expozițiile costă 47 de lei; copiii, elevii și studenții plătesc mult mai puțin.$$, 46.1757, 21.3171, 100),

-- 3 · Teatrul Clasic
(3, 1, 'Un teatru din 1874', $$Clădirea neoclasică din capătul Pieței Avram Iancu a fost inaugurată în 1874 și a trecut prin incendii și renovări, păstrându-și însă fațada cu coloane. Teatrul poartă numele scriitorului Ioan Slavici, născut în Șiria, la poalele podgoriei. Este cea mai veche instituție de spectacole a orașului.$$, 46.1726, 21.3153, 90),
(3, 2, 'Sala Mare și Sala Studio', $$Spectacolele de repertoriu se joacă în Sala Mare, iar producțiile mai intime, în Sala Studio. În noiembrie, teatrul organizează Festivalul Internațional de Teatru Nou, dedicat dramaturgiei contemporane, cu ateliere și spectacole invitate. Biletele se iau de la agenția teatrului sau online.$$, 46.1726, 21.3153, 80),
(3, 3, 'Piața Avram Iancu', $$Piața din fața teatrului a fost, la începutul secolului al XIX-lea, centrul comercial și politic al Aradului. Astăzi este loc de târguri și de evenimente: aici se ține „Piața Producătorilor Arădeni”, iar de aici pornește Bulevardul Revoluției, axa pe care se înșiră cele mai frumoase palate ale orașului.$$, 46.1722, 21.3158, 80),

-- 4 · Palatul Administrativ
(4, 1, 'Turnul cu orologiu', $$Turnul de 54 de metri este reperul centrului. Orologiul a fost adus din Elveția, iar mecanismul lui cântă „Oda bucuriei” la ore fixe. Clădirea a fost ridicată între 1872 și 1874, după un plan al arhitectului budapestan Ödön Lechner, modificat de arădeanul Ferenc Pekár, într-un stil neorenascentist care amintește de primăriile medievale târzii din Flandra.$$, 46.1768, 21.3145, 110),
(4, 2, 'Bulevardul Revoluției', $$Din fața Primăriei, priviți de-a lungul bulevardului: Palatul Neuman, Palatul Cenad, Palatul Băncii Naționale, catedralele și, în capăt, Palatul Cultural. Aradul a fost numit „Mica Vienă” tocmai pentru aceste fațade de la sfârșitul secolului al XIX-lea și începutul secolului XX. Cea mai bună plimbare din oraș este de aici până la Mureș, cam 1,2 kilometri.$$, 46.1760, 21.3150, 100),
(4, 3, 'Vitraliile și Parcul Reconcilierii', $$În interior, vitraliile realizate în 1960 de Sever Frențiu reprezintă anotimpurile și lunile anului, cu zeul timpului, Cronos. Interiorul se vizitează doar la tururi anunțate. În spatele palatului se află Parcul Reconcilierii, iar în apropiere Turnul de Apă. În perioada sărbătorilor, platoul din fața Primăriei devine una dintre zonele Târgului de Crăciun.$$, 46.1775, 21.3135, 100),

-- 5 · Biserica Roșie
(5, 1, 'Cărămida roșie și neogoticul', $$Biserica evanghelică-luterană a fost construită între 1905 și 1906 de constructorul Iosef Frick, după planurile lui Ludovic Szántay. Fațadele din cărămidă roșie șlefuită i-au dat numele popular. Turnul principal are 46 de metri, iar ferestrele înalte, în arc frânt, și contraforturile sunt tipic neogotice.$$, 46.1740, 21.3160, 90),
(5, 2, 'Interiorul și orga', $$Dacă ușa e deschisă, intrați: interiorul e luminos și sobru, cu o orgă folosită la concerte organizate împreună cu Filarmonica. Biserica deservește comunitatea maghiară evanghelică din oraș și este una dintre cele mai fotografiate clădiri de pe bulevard.$$, 46.1740, 21.3160, 70),

-- 6 · Catedrala Sfânta Treime
(6, 1, 'Cea mai mare biserică din vestul țării', $$Piatra de temelie a fost pusă la 24 noiembrie 1991, iar catedrala a fost sfințită în 2008; pictura interioară a fost terminată în 2018. Are 63 de metri lungime și 36 lățime, cu cupole în stil bizantin și elemente inspirate de la Curtea de Argeș. Este sediul Arhiepiscopiei Aradului.$$, 46.1692, 21.3182, 100),
(6, 2, 'Piața Catedralei', $$Piața din față e locul marilor evenimente din oraș: aici se deschide pe 14 noiembrie Târgul de Crăciun, cu zeci de căsuțe, concerte de colinde în weekend și ateliere pentru copii, până în ianuarie. Lângă piață se află lacul și parcul din Podgoria, bune pentru o pauză.$$, 46.1690, 21.3180, 80),

-- 7 · Catedrala Sf. Anton
(7, 1, 'Pietà de deasupra intrării', $$Catedrala romano-catolică a fost ridicată între 1902 și 1904, după planurile arhitectului Emil Tabacovici, pe locul unei biserici baroce. Coloanele monumentale și intrarea boltită impresionează, iar deasupra porții se află o copie în marmură albă a celebrei Pietà a lui Michelangelo.$$, 46.1752, 21.3151, 80),

-- 8 · Turnul de Apă (exterior)
(8, 1, 'Un donjon pentru apă', $$Turnul a fost construit în 1896 de firma engleză Shone & Ault, cea care a realizat primul sistem de alimentare cu apă al Aradului. Are 35 de metri și un rezervor de 300 de metri cubi la ultimul nivel. Arhitectura imită un donjon de cetate medievală, cu balcoane și ferestre decorate; a funcționat până în 1956.$$, 46.1792, 21.3118, 90),
(8, 2, 'Galeria care s-a închis', $$După 1990 turnul a trecut în proprietate privată și a găzduit o galerie de artă, expoziții despre apă și despre pompierii orașului și o terasă panoramică în fostul rezervor. Din 2024 este închis publicului, fără o dată de redeschidere. Rămâne însă unul dintre cele mai fotogenice colțuri ale Aradului, lângă Parcul Reconcilierii.$$, 46.1792, 21.3118, 80),

-- 9 · Faleza Mureșului
(9, 1, 'Promenada', $$Faleza se întinde pe câțiva kilometri de-a lungul malului drept al Mureșului, între Ștrandul Neptun și Parcul Copiilor. Alei pentru plimbat și alergat, terenuri de sport, locuri de joacă și terase. De aici se vede cel mai bine Cetatea, pe malul opus, mai ales la apus.$$, 46.1745, 21.3215, 80),
(9, 2, 'Podul Traian și Cetatea', $$Podul Traian leagă centrul de cartierul Subcetate și de intrarea în Cetate. De pe pod aveți panorama zidurilor și a bastioanelor. Faleza este și locul acțiunilor comunitare din aplicație: plantări de copaci și curățenii organizate de Primărie, pentru care primiți puncte.$$, 46.1738, 21.3250, 70),

-- 10 · Lunca Mureșului
(10, 1, 'Centrul de vizitare Ceala', $$Parcul Natural Lunca Mureșului protejează pădurea de luncă și brațele vechi ale râului de la vest de oraș. Punctul de plecare este Centrul de vizitare Ceala, de unde pornesc trasee marcate pentru plimbare și bicicletă. Luați apă și încălțăminte bună; pe cărări poate fi noroi după ploi.$$, 46.1900, 21.2650, 80),
(10, 2, 'Păsări și brațe moarte', $$Zona este un paradis pentru observarea păsărilor: stârci, egrete, răpitoare și, în sezon, zeci de specii migratoare. Brațele moarte ale Mureșului formează lacuri liniștite, iar pădurea de stejar și frasin este una dintre ultimele de acest fel din câmpia de vest. Parcul este și locul curățeniilor comunitare de primăvară și toamnă.$$, 46.1900, 21.2650, 80),

-- 11 · Podgoria Miniș
(11, 1, 'Dealurile Zarandului și Cadarca', $$Podgoria Miniș–Măderat se întinde pe terminațiile Dealurilor Zarandului, pe soluri bogate în fier, cu expunere sudică. Aici s-a făcut vin de secole; vinul-simbol este Cadarca, un roșu aromat și viu, alături de Mustoasa de Măderat, un alb local, de Fetească regală și Riesling italian.$$, 46.1370, 21.6050, 90),
(11, 2, 'Muzeul Viei și Vinului', $$Muzeul, înființat în 1988 în incinta Stațiunii de Cercetare Vitivinicolă Miniș, aparține Complexului Muzeal Arad și expune unelte, prese, documente și fotografii despre istoria viticulturii locale. Este deschis de marți până duminică, între 9 și 17.$$, 46.1370, 21.6050, 70),
(11, 3, 'Cramele și Drumul Vinului', $$Cramele din Miniș, Ghioroc, Păuliș și Șiria primesc vizitatori pentru degustări, aproape toate cu rezervare prealabilă, de obicei în timpul săptămânii; în weekend doar grupuri. O degustare cu platou durează cam o oră și costă în jur de 100–125 de lei. Drumul Vinului, modernizat de Consiliul Județean, leagă satele podgoriei.$$, 46.1340, 21.6180, 90),
(11, 4, 'Cu tramvaiul la podgorie', $$Dacă nu conduceți, luați tramvaiul istoric Arad–Ghioroc, „Săgeata Verde”, care traversează câmpia până la poalele dealurilor; la Ghioroc există și Muzeul Tramvaiului Electric. De la depou, cramele sunt la câțiva kilometri, cu microbuz sau pe jos.$$, 46.1420, 21.5980, 70),

-- 12 · Macea
(12, 1, 'Castelul', $$Castelul de la Macea, monument istoric, îmbină barocul târziu cu elemente gotice și bizantine, o combinație rară în arhitectura nobiliară a regiunii. A fost construit și extins în etape, de-a lungul mai multor generații. Astăzi aparține Universității de Vest „Vasile Goldiș” și găzduiește muzeele grădinii.$$, 46.3860, 21.3167, 80),
(12, 2, 'Grădina Botanică „Pavel Covaci”', $$Grădina are 21,5 hectare și peste 3.800 de specii și soiuri: alpinariu, rozariu, sectorul plantelor aromatice și medicinale, colecția dendrologică și un bambus impresionant. Toamna este cel mai spectaculos sezon. Programul: în timpul săptămânii 8–16, în weekend 9–19 din martie până în noiembrie; iarna este închisă.$$, 46.3860, 21.3167, 90),
(12, 3, 'Cum ajungeți', $$Macea e la 25 de kilometri nord de Arad, 20–30 de minute cu mașina. Cu trenul, Arad–Curtici durează 15 minute, apoi există microbuze sau o plimbare de o oră până în sat. Pentru grupuri și școli, vizitele se programează telefonic.$$, 46.3860, 21.3167, 60)
ON CONFLICT DO NOTHING;

SELECT setval('places_id_seq', (SELECT MAX(id) FROM places));
SELECT setval('guide_points_id_seq', (SELECT MAX(id) FROM guide_points));
